package com.projexa.coaching.academics.controller;
import com.projexa.coaching.academics.entity.AcademicClass; import com.projexa.coaching.academics.service.AcademicClassService; import com.projexa.coaching.common.responses.ApiResponse; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/classes") public class AcademicClassController { private final AcademicClassService service; public AcademicClassController(AcademicClassService service){this.service=service;} @GetMapping @PreAuthorize("hasAuthority('dashboard.read') or hasAuthority('settings.manage') or hasAuthority('students.read')") public ApiResponse<List<AcademicClass>> list(){return ApiResponse.ok(service.list());} @GetMapping("/{id}") @PreAuthorize("hasAuthority('dashboard.read') or hasAuthority('settings.manage') or hasAuthority('students.read')") public ApiResponse<AcademicClass> get(@PathVariable UUID id){return ApiResponse.ok(service.get(id));} @PostMapping @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.create')") public ApiResponse<AcademicClass> create(@RequestBody AcademicClass item){return ApiResponse.ok(service.create(item));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.update')") public ApiResponse<AcademicClass> update(@PathVariable UUID id,@RequestBody AcademicClass item){return ApiResponse.ok(service.update(id,item));} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.delete')") public ApiResponse<Void> delete(@PathVariable UUID id){service.delete(id);return ApiResponse.ok(null);} }